import java.io.ByteArrayInputStream
import java.io.IOException
import java.io.InputStream
import java.io.PrintWriter
import java.util.Arrays
import java.util.InputMismatchException

class Test {
    private var `is`: InputStream = System.in
    private var out: PrintWriter = PrintWriter(System.out)
    private val INPUT = ""
    private lateinit var F: LongArray

    private fun solve() {
        F = LongArray(17)
        F[0] = 1
        for (i in 1..16) F[i] = F[i - 1] * i

        var K = nl()
        val t = ni()
        K--
        gouter@ for (len in 1..Int.MAX_VALUE) {
            var ret = 0L
            val rem = IntArray(16) { t }
            outer@ for (i in 0 until len) {
                for (j in (if (i == 0) 1 else 0) until 16) {
                    rem[j]--
                    val count = count(rem, len - 1 - i)
                    if (K < count) {
                        ret = ret * 16 + j
                        continue@outer
                    } else {
                        K -= count
                    }
                    rem[j]++
                }
                continue@gouter
            }
            out.println(ret.toString(16))
            return
        }
    }

    private fun count(rem: IntArray, len: Int): Long {
        val dp = LongArray(len + 1)
        dp[0] = F[len]
        for (x in rem) {
            if (x < 0) return 0
            if (x == 0) continue
            for (i in len downTo 0) {
                for (j in 1..x) {
                    if (i - j < 0) break
                    dp[i] += dp[i - j] / F[j]
                }
            }
        }
        return dp[len]
    }

    @Throws(Exception::class)
    private fun run() {
        `is` = if (oj) System.in else ByteArrayInputStream(INPUT.toByteArray())
        out = PrintWriter(System.out)

        val s = System.currentTimeMillis()
        solve()
        out.flush()
        tr(System.currentTimeMillis() - s + "ms")
    }

    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            Test().run()
        }
    }

    private val inbuf = ByteArray(1024)
    private var lenbuf = 0
    private var ptrbuf = 0

    private fun readByte(): Int {
        if (lenbuf == -1) throw InputMismatchException()
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0
            try {
                lenbuf = `is`.read(inbuf)
            } catch (e: IOException) {
                throw InputMismatchException()
            }
            if (lenbuf <= 0) return -1
        }
        return (inbuf[ptrbuf++].toInt() and 0xFF)
    }

    private fun isSpaceChar(c: Int): Boolean = !(c in 33..126)

    private fun skip(): Int {
        var b: Int
        while (readByte().also { b = it } != -1 && isSpaceChar(b)) {}
        return b
    }

    private fun ns(): String {
        var b = skip()
        val sb = StringBuilder()
        while (!isSpaceChar(b)) {
            sb.appendCodePoint(b)
            b = readByte()
        }
        return sb.toString()
    }

    private fun ni(): Int {
        var num = 0
        var b: Int
        var minus = false
        b = readByte()
        while (b != -1 && !((b in '0'..'9') || b == '-')) {
            b = readByte()
        }
        if (b == '-') {
            minus = true
            b = readByte()
        }
        while (true) {
            if (b in '0'..'9') {
                num = num * 10 + (b - '0')
            } else {
                return if (minus) -num else num
            }
            b = readByte()
        }
    }

    private fun nl(): Long {
        var num = 0L
        var b: Int
        var minus = false
        b = readByte()
        while (b != -1 && !((b in '0'..'9') || b == '-')) {
            b = readByte()
        }
        if (b == '-') {
            minus = true
            b = readByte()
        }
        while (true) {
            if (b in '0'..'9') {
                num = num * 10 + (b - '0')
            } else {
                return if (minus) -num else num
            }
            b = readByte()
        }
    }

    private val oj = true // System.getProperty("ONLINE_JUDGE") != null
    private fun tr(vararg o: Any?) {
        if (!oj) println(Arrays.deepToString(o))
    }
}

