                    long count = count(rem, len-1-i);
                    if(K < count){
                        ret = ret * 16 + j;
                        continue outer;
                    }else{
                        K -= count;
                    }
                    rem[j]++;
                }
                continue gouter;
            }
            out.println(Long.toHexString(ret));
            return;
        }
    }

    long count(int[] rem, int len)
    {
        long[] dp = new long[len+1];
        dp[0] = F[len];
        for(int x : rem){
            if(x < 0)return 0;
            if(x == 0)continue;
            for(int i = len;i >= 0;i--){
                for (int j = 1; j <= x; j++) {
                    if ((i - j) < 0) break;
